@callme_friend：linux-3.17中gic_handle_irq的代码如下：
－－－－－－－－－－－－－－－－－－－－－－－－－－－－－－－－－－－－
static void __exception_irq_entry gic_handle_irq(struct pt_regs *regs)
{
	u32 irqstat, irqnr;
	struct gic_chip_data *gic = &gic_data[0];
	void __iomem *cpu_base = gic_data_cpu_base(gic);

	do {
		irqstat = readl_relaxed(cpu_base + GIC_CPU_INTACK);
		irqnr = irqstat & GICC_IAR_INT_ID_MASK;

		if (likely(irqnr > 15 && irqnr < 1021)) {
			irqnr = irq_find_mapping(gic->domain, irqnr);
			handle_IRQ(irqnr, regs);
			continue;
		}
		if (irqnr < 16) {
			writel_relaxed(irqstat, cpu_base + GIC_CPU_EOI);
#ifdef CONFIG_SMP
			handle_IPI(irqnr, regs);
#endif
			continue;
		}
		break;
	} while (1);
}
－－－－－－－－－－－－－－－－－－－－－－－－－－－－－－－－－－－－－
irq_find_mapping是将hw interrupt ID转变成IRQ Number（当然是在root gic对应的irq domain上了），之后调用handle_IRQ处理这个IRQ。如果是级联的情况，那么root gic解析的这个IRQ对应的handler就是gic_handle_cascade_irq（你的猜测是对的），代码如下：
－－－－－－－－－－－－－－－－－－－－－－－－－－－－－－－－－－－－
static void gic_handle_cascade_irq(unsigned int irq, struct irq_desc *desc)
{
	struct gic_chip_data *chip_data = irq_get_handler_data(irq);
	struct irq_chip *chip = irq_get_chip(irq);
	unsigned int cascade_irq, gic_irq;
	unsigned long status;

	chained_irq_enter(chip, desc);

	raw_spin_lock(&irq_controller_lock);
	status = readl_relaxed(gic_data_cpu_base(chip_data) + GIC_CPU_INTACK);
	raw_spin_unlock(&irq_controller_lock);

	gic_irq = (status & 0x3ff);
	if (gic_irq == 1023)
		goto out;

	cascade_irq = irq_find_mapping(chip_data->domain, gic_irq);
	if (unlikely(gic_irq < 32 || gic_irq > 1020))
		handle_bad_irq(cascade_irq, desc);
	else
		generic_handle_irq(cascade_irq);

 out:
	chained_irq_exit(chip, desc);
}
－－－－－－－－－－－－－－－－－－－－－－－－－－－－－－－－－－－－－－－
同样的，irq_find_mapping将hw interrupt ID转变成IRQ Number（当然是在second gic对应的irq domain上了，传递给irq_find_mapping的domain参数是和上次不一样的）

关于级联的中断处理，我认为博文漏掉了一个domain如何衔接的片段。
void gic_handle_irq(struct pt_regs *regs)
{
	struct gic_chip_data *gic = &gic_data[0];
	void __iomem *cpu_base = gic_data_cpu_base(gic);

	irqstat = readl_relaxed(cpu_base + GIC_CPU_INTACK);
	irqnr = irqstat & GICC_IAR_INT_ID_MASK;
	
	irqnr = irq_find_mapping(gic->domain, irqnr);
	handle_IRQ(irqnr, regs);	
		generic_handle_irq(irq)
			desc->handle_irq(irq, desc);  //对于级联，应是gic_handle_cascade_irq()
}
 void gic_handle_cascade_irq(unsigned int irq, struct irq_desc *desc)
{    //gic_handle_cascade_irq()传递进来的参数是root GIC的级联点的virq号
	struct gic_chip_data *chip_data = irq_get_handler_data(irq);-------------（1）
	struct irq_chip *chip = irq_get_chip(irq);
	unsigned int cascade_irq, gic_irq;
	unsigned long status;

	status = readl_relaxed(gic_data_cpu_base(chip_data) + GIC_CPU_INTACK);  //此处居然是次级 GIC的读取操作了
	gic_irq = (status & 0x3ff);

	cascade_irq = irq_find_mapping(chip_data->domain, gic_irq);

	generic_handle_irq(cascade_irq);
		desc->handle_irq(irq, desc);
}

对于gic_handle_cascade_irq()中的处理，没显式看到domain的转换代码。之前一直卡在这里。
对于（1）代码，才是转换domain的关键；因为在次级GIC初始化的时候，有如下代码：
if (parent) {
	gic_cascade_irq(gic_cnt, irq);
			if (irq_set_handler_data(irq, &gic_data[gic_nr]) != 0)--------(2)
				BUG();
			irq_set_chained_handler(irq, gic_handle_cascade_irq);
}
代码（2）中，是将次级GIC_DATA保存在上级GIC的级联点对应的irq_desc中。以此来保证代码（1）中domain转换。

